import manifest from "./photos.generated.json";
import type { Photo, PhotoCollection } from "./types";

// Generated by `npm run photos:sync`. Edit photos/photos.json for titles, alt text, covers, order.
export const photos = manifest.photos as Photo[];
export const collections = manifest.collections as PhotoCollection[];

export const getPhoto = (id: string) => photos.find((p) => p.id === id);

export const getCollection = (id: string) => collections.find((c) => c.id === id);

/** Photos in one collection, in display order. */
export const photosInCollection = (collectionId: string) => photos.filter((p) => p.collection === collectionId);

export const collectionCover = (c: PhotoCollection) => getPhoto(c.cover);

export const featuredPhotos = photos.filter((p) => p.featured);
